def write(vid,spec,sequence,excluded=[]):
 d=b/vid;m=json.loads((d/'meta.json').read_text());frames=json.loads((d/'captures/validated/manifest.json').read_text())['frames'];lookup={r['label']:r for r in frames};screens=[];stateMap={}
 for i,row in enumerate(spec,1):
  family,title,scope,presentation,structures,controls,labels,existing,notes=row;sid=f'{vid}-S{i:02d}';states=[]
  for k,(key,label,kind) in enumerate(labels):
   r=lookup[key];q={'id':sid+'-'+chr(65+k),'label':label,'kindObserved':kind,'representative':{x:r[x] for x in ('requested','actual','file','width','height')},'originalSizePNG':{x:r[x] for x in ('requested','actual','file','width','height','format')},'gameCrop':r['gameCrop'],'stableSampleRangesSeconds':[[r['actual'],r['actual']]],'basis':'Direct original PNG at recorded input PTS; isolated samples do not prove a click, duration, easing or complete timeline.','notes':[]};states.append(q);stateMap[key]=(sid,q['id'],r['actual'])
  screens.append({'id':sid,'canonicalFamily':family,'observedTitle':title,'scope':scope,'presentationObserved':presentation,'states':states,'visibleStructure':structures,'visibleControls':[{'label':c,'activationProven':False} for c in controls],'existingDesignScreenId':existing,'existingDesignMatchStatus':'family candidate only; does not prove matching states or transitions' if existing else 'not assembled in r277 ten-screen sample','implementationStatus':'video observed only; source/design unchanged','entryBeforeClip':None,'exitOutsideObservedWindow':None,'notes':notes})
 ts=[]
 for i,(a,z,outcome,candidate) in enumerate(sequence,1):
  x=stateMap[a];y=stateMap[z];assert x[2]<y[2],(a,z)
  ts.append({'id':f'{vid}-T{i:02d}','scope':'state' if x[0]==y[0] else 'screen','fromScreenId':x[0],'toScreenId':y[0],'fromStateId':x[1],'toStateId':y[1],'observedWindowSeconds':[x[2],y[2]],'evidence':[lookup[a]['file'],lookup[z]['file']],'observedOutcome':outcome,'trigger':None,'visibleControlCandidate':candidate,'inputActivationProven':False,'implementationLinkVerified':False,'runtimeTarget':None,'notes':['The visible before/after sequence is observed. Input event, exact activation time and external URI remain unverified.']})
 j={'format':'ui-studio-video-observation','version':1,'videoId':vid,'status':'proposal awaiting review','source':m,'method':{'decoder':m['decoder'],'originalReadOnly':True,'samplingReviewStep':.5,'representatives':'direct PNG with ffmpeg selected input PTS','jpegReviewLabels':'nominal fps=2 schedule only; never substitute for input PTS'},'existingDesignComparison':{'projectId':'ux-gjs-0d80d7fe','revision':277,'match':'family candidate, not visual equivalence'},'counts':{'screenRecords':len(screens),'stateRecords':sum(len(x['states']) for x in screens),'transitionRecords':len(ts)},'screens':screens,'excludedTransitionAnimations':excluded,'unknowns':['Input events and exact trigger times are not proven by these screenshots.','Unobserved destinations and external URI remain null.','No game code, app install, consent, chat send or payment performed.']}
 (d/'screens.json').write_text(json.dumps(j,ensure_ascii=False,indent=2));(d/'transitions.json').write_text(json.dumps({'format':'ui-studio-video-transitions','version':1,'videoId':vid,'basis':'observed sample sequence, no input event proof','count':len(ts),'transitions':ts},ensure_ascii=False,indent=2))
 (d/'notes.md').write_text('# '+vid+' '+m['name']+'\n\n제안(검수 대기). 원본 PNG와 실제 입력 PTS를 기록했습니다. fps=2 JPEG의 예정 시각을 실제 PTS로 쓰지 않습니다.\n\n'+ '\n'.join('- '+s['observedTitle']+' / '+s['scope']+' / '+str(len(s['states']))+'상태' for s in screens)+'\n\n외부 앱 화면은 영상 참고로만 분리하며 앱 설치·동의·로그인·메시지·결제를 수행하지 않았습니다. 원본의 글자/그림을 제작 리소스에 붙이지 않습니다.\n')
 print(vid,len(screens),sum(len(s['states']) for s in screens),len(ts))
